  stk asegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m -> accessible m bs 8 -> bs mod 8 = 0 ->
  evt asegs (bsd_seg2_post sp gp tp (wz bs) s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc stb lo m)
    (MS (mkR rax sp gp tp t0 t1 t2 (wz bs) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BSD_RET1) fc None m (seg_rom asegs)).
